const hoy = $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd');
const ahora = $now.setZone('Europe/Madrid').toFormat('dd/MM/yyyy HH:mm');
return [{ json: { hoy, ahora } }];

const hoy = $('Calcular hoy').first().json.hoy;
const ahora = $('Calcular hoy').first().json.ahora;
const ventas = $('Ventas de hoy').all().map(i => i.json).filter(r => r && r.id !== undefined);
const abonos = $('Abonos de hoy').all().map(i => i.json).filter(r => r && r.id !== undefined);
const apartados = $('Apartados activos').all().map(i => i.json).filter(r => r && r.id !== undefined);

const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const sumCents = (items) => items.reduce((s, r) => s + Math.round(Number(r.importe || 0) * 100), 0);
const totalVentasCents = sumCents(ventas);
const totalAbonosCents = sumCents(abonos);
const totalHoyCents = totalVentasCents + totalAbonosCents;

const formas = ['efectivo','tarjeta','bizum'];
const porFormaCents = (items) => formas.reduce((acc, f) => {
  acc[f] = items.filter(r => String(r.forma_pago||'').toLowerCase() === f).reduce((s,r)=> s + Math.round(Number(r.importe||0)*100), 0);
  return acc;
}, {});
const vForma = porFormaCents(ventas);
const aForma = porFormaCents(abonos);

const limite = new Date(hoy + 'T00:00:00');
limite.setDate(limite.getDate() + 7);
const proximos = apartados
  .filter(a => a.fecha_limite && new Date(a.fecha_limite + 'T00:00:00') >= new Date(hoy + 'T00:00:00') && new Date(a.fecha_limite + 'T00:00:00') <= limite)
  .sort((a,b) => String(a.fecha_limite).localeCompare(String(b.fecha_limite)));

const pendienteTotalCents = apartados.reduce((s,a) => s + Math.round(Number(a.pendiente || 0) * 100), 0);

const fmt = (cents) => (cents / 100).toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
const fechaCorta = (f) => String(f).split('-').reverse().join('/');

const filas = proximos.map(a =>
  '<tr><td>' + esc(a.cliente) + '</td><td>' + esc(a.producto) + ' ' + esc(a.talla||'') + '</td><td>' + fmt(Math.round(Number(a.pendiente||0)*100)) + '</td><td>' + fechaCorta(a.fecha_limite) + '</td></tr>'
).join('');

const html = '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel Marisa</title>'
+ '<style>@import url("https://fonts.googleapis.com/css2?family=Nunito+Sans:wght@400;700&family=Fraunces:opsz,wght@9..144,700&display=swap");body{font-family:"Nunito Sans",system-ui,sans-serif;margin:0;padding:16px;background:#f3ebdd;color:#2a1c13}.card{position:relative;background:#fffaf1;border:1px solid #dccab0;border-radius:12px;padding:18px;margin-bottom:16px;box-shadow:0 2px 6px rgba(58,36,24,.08)}.card::before{content:"";position:absolute;inset:5px;border:1.5px dashed #c9b08c;border-radius:7px;pointer-events:none}body>.card:first-of-type{background:#3a2418;border-color:#3a2418;color:#fbf3e6}body>.card:first-of-type::before{border-color:#a77b55}body>.card:first-of-type p{color:#dcc8b0!important}h1{font-family:Fraunces,Georgia,serif;font-size:24px;margin:0 0 6px}h2{font-family:Fraunces,Georgia,serif;font-size:17px;margin:0 0 8px;color:#7b4a2a}.big{font-family:Fraunces,Georgia,serif;font-size:30px;font-weight:700;color:#1f4d3a}.row{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px dashed #dccab0}.table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:8px 4px;border-bottom:1px solid #dccab0;text-align:left}th{color:#6a5444;font-weight:700;font-size:12px;text-transform:uppercase;letter-spacing:.05em}.empty{color:#6a5444;font-style:italic;padding:8px 0}</style>'
+ '</head><body>'
+ '<div class="card"><h1>Panel de Marisa</h1><p style="margin:0;color:#6a5444;font-size:13px">Actualizado: ' + ahora + '</p></div>'
+ '<div class="card"><h2>Cobrado hoy</h2><div class="big">' + fmt(totalHoyCents) + '</div>'
+ '<div class="row"><span>Ventas directas</span><span>' + fmt(totalVentasCents) + '</span></div>'
+ '<div class="row"><span>Abonos de apartados</span><span>' + fmt(totalAbonosCents) + '</span></div>'
+ '<div class="row"><span>Efectivo</span><span>' + fmt(vForma.efectivo + aForma.efectivo) + '</span></div>'
+ '<div class="row"><span>Tarjeta</span><span>' + fmt(vForma.tarjeta + aForma.tarjeta) + '</span></div>'
+ '<div class="row"><span>Bizum</span><span>' + fmt(vForma.bizum + aForma.bizum) + '</span></div>'
+ '</div>'
+ '<div class="card"><h2>Apartados por vencer (7 días)</h2>'
+ (proximos.length ? '<table class="table"><thead><tr><th>Cliente</th><th>Producto</th><th>Pendiente</th><th>Límite</th></tr></thead><tbody>' + filas + '</tbody></table>' : '<div class="empty">No hay apartados próximos a vencer.</div>')
+ '</div>'
+ '<div class="card"><h2>Total pendiente de cobro</h2><div class="big">' + fmt(pendienteTotalCents) + '</div><p style="margin:4px 0 0;color:#6a5444;font-size:13px">' + apartados.length + ' apartados activos</p></div>'
+ '</body></html>';

return [{ json: { html } }];
